covered = set()
for i, (title, ids, setup, steps, expected) in enumerate(journeys, 1):
    mapped = ids.split(); covered.update(mapped)
    statuses = ', '.join(f'{s}: {sum(by_id[id]["status"] == s for id in mapped)}' for s in ['PASS','FAIL','BLOCKED'])
    out += [f'### HUMAN-UAT-J{i:03} — {title}', '', f'Mapped tests: {ids}. Priority: P1. Agent results: {statuses}; consult each registry row.', '', f'Setup: {setup}', '', 'Steps:', '']
    out += [f'{n}. {step}' for n, step in enumerate(steps, 1)]
    out += ['', f'Expected: {expected}', '', 'Human result: **PENDING**. [ ] PASS [ ] FAIL. Notes / screenshot / timestamp / browser: ____________________', '']

