out += ['## One verification ticket per canonical test', '', 'Execute P1 tickets before P2. Each ticket inherits the exact fixture IDs and methods from the priority journeys above and the private fixture sheet. A QA operator must prepare unavailable providers, failure states, races or restore fixtures before its human test can be performed. Mark the result only after the entire stated expected condition is observed.', '']
for r in sorted(rows, key=lambda r:(r['priority'],r['ordinal'])):
    actor, route, action = routes[r['group']]
    journey_links = [f'HUMAN-UAT-J{i:03}' for i,j in enumerate(journeys,1) if r['id'] in j[1].split()]
    out += [f"### HUMAN-UAT-{r['ordinal']:03} — {r['id']}", '', f"Priority: {r['priority']}. Agent result: {r['status']}. Bug: {', '.join(r['bugs']) or 'none confirmed'}. Journey: {', '.join(journey_links) or 'use the specific ticket procedure below'}.", '', f'Setup: {actor}; use the private fixture sheet with exactly the lifecycle/identity state in the expected condition below. Obtain any required failure/race/provider fixture from QA before starting.', '', 'Steps:', '', f'1. In the specified isolated profile open {route}. Record the initial visible state and fixture resource IDs.', f'2. {action}', '3. Check the complete expected condition below, including the negative request or related history/ownership where named. Record the actual result and screenshot; ask QA for the matching DB/audit evidence for server-only requirements.', '4. Restore/reset only the disposable fixture before the next test. Do not mark PASS if a prerequisite or required observation is unavailable.', '', f"Expected: {r['scenario']}", '', 'Human result: **PENDING**. [ ] PASS [ ] FAIL. Notes / evidence / timestamp / browser: ____________________', '']

